package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaViDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("Nhìn thấy trái đầu tiên", "Lạy Allah, xin ban phước lành cho chúng tôi về thành quả của chúng tôi, ban phước lành cho chúng tôi trong thành phố của chúng tôi và ban phước lành cho chúng tôi trong sa' và bùn (biện pháp) của chúng tôi.", "Khi nhìn thấy trái cây đầu mùa.", "Một dua cho phước lành trong việc cung cấp và trong thành phố của một người."),
        "dua_good_news" to DuaText("Khi có tin vui", "Mọi lời khen ngợi đều dâng lên Allah, Đấng đã giúp đỡ những điều tốt đẹp được hoàn thành.", "Khi nhận được tin vui (và thực hiện lễ lạy tạ ơn).", "Nhà tiên tri ﷺ đã nói điều này khi nhìn thấy thứ gì đó mà ông ấy thích."),
        "dua_looking_mirror" to DuaText("Nhìn vào gương", "Ôi Allah, giống như Ngài đã làm cho bề ngoài của tôi trở nên tốt đẹp, hãy làm cho tính cách của tôi cũng tốt đẹp như vậy.", "Khi nhìn vào gương.", "Nhà tiên tri ﷺ đã thực hiện điều này (nó được thiết lập ngay cả khi không đề cập đến chiếc gương)."),
        "dua_rabbana_taqabbal" to DuaText("Chấp nhận chứng thư", "Lạy Chúa, xin chấp nhận điều này từ chúng con; quả thật Ngài là Đấng Hằng Nghe, Đấng Biết Tất Cả. Và chấp nhận sự ăn năn của chúng tôi; quả thực Ngài là Đấng Chấp nhận sự ăn năn, Đấng Thương Xót.", "Câu hỏi của Ibrahim và Isma'il (AS) khi xây dựng Ka'bah.", "Một sự chấp nhận sau mỗi việc tốt."),
        "dua_muawwidhat" to DuaText("Ba Quls (Mu'awwidhat)", "(Surah al-Ikhlas) Hãy nói: Ngài là Allah, Đấng duy nhất. Allah, Đấng Tự túc. Anh ta không sinh ra cũng không được sinh ra. Và không ai có thể so sánh được với Ngài.\n\n(Surah al-Falaq) Hãy nói: Tôi tìm nơi ẩn náu nơi Chúa của bình minh, khỏi cái ác của những gì Ngài đã tạo ra, khỏi cái ác của bóng tối khi nó lắng xuống, khỏi cái ác của những kẻ thổi nút, và khỏi cái ác của kẻ đố kỵ khi hắn ghen tị.\n\n(Surah an-Nas) Hãy nói: Tôi tìm nơi nương tựa vào Chúa của nhân loại, Vua của nhân loại, Thần của nhân loại, khỏi cái ác của kẻ thì thầm rút lui, kẻ thì thầm vào trái tim nhân loại, giữa loài jinn và nhân loại.", "Ba surahs ba lần vào mỗi buổi sáng và buổi tối, và trước khi đi ngủ, thổi vào tay và lau khắp cơ thể.", "Trì tụng chúng ba lần vào buổi sáng và buổi tối là đủ đối với mọi thứ."),
        "dua_sabr" to DuaText("Vì sự kiên nhẫn và kiên định", "Lạy Chúa, xin ban sự kiên nhẫn cho chúng con, làm cho đôi chân chúng con vững vàng và giúp chúng con chống lại những kẻ không có đức tin.", "Trong lúc khó khăn và đối đầu.", "Dua của quân đội Talut."),
        "dua_rabbana_innana_amanna" to DuaText("Sự tha thứ và bảo vệ khỏi lửa", "Lạy Chúa, chúng con đã tin, xin tha tội cho chúng con và bảo vệ chúng con khỏi hình phạt của Lửa.", "Một bản dua Kinh Qur'an.", "Một dua được đề cập trong số những phẩm chất của người kính sợ Chúa."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Hướng dẫn trong công việc của chúng tôi (Ashab al-Kahf)", "Lạy Chúa, xin ban cho chúng con lòng thương xót của Chúa và chuẩn bị cho chúng con sự hướng dẫn đúng đắn trong công việc của chúng con.", "Dua của Người Hang.", "Hướng dẫn trong các quyết định và tình huống khó khăn."),
        "dua_musa_faqir" to DuaText("Dua của Musa (AS) để cung cấp", "Lạy Chúa, con thực sự cần bất cứ điều tốt lành nào Chúa ban xuống cho con.", "Tìm kiếm sự cung cấp và điều tốt đẹp — dua của Musa (AS) ở Madyan.", "Sau cuộc dua này, Allah đã ban cho Musa (AS) một ngôi nhà, một công việc và một người vợ."),
        "dua_ayyub" to DuaText("Dua của Ayyub (AS) bị bệnh", "(Lạy Chúa của con), sự tổn hại đã chạm đến con, và Chúa là Đấng Nhân từ nhất trong những kẻ hay thương xót.", "Trong bệnh tật và đau khổ.", "Allah đã xóa bỏ nỗi đau khổ của Ayyub (AS)."),
        "dua_husn_khatimah" to DuaText("Chết như một người Hồi giáo (Yusuf AS)", "Đấng tạo thành trời và đất, Ngài là Đấng bảo vệ con ở đời này và đời sau. Làm cho tôi chết như một người Hồi giáo và tham gia cùng tôi với người chính nghĩa.", "Một dua cho một kết thúc tốt đẹp.", "Dua của Tiên tri Yusuf (AS)."),
        "dua_shaitan_hamazat" to DuaText("Nơi ẩn náu khỏi lời thì thầm của quỷ dữ", "Lạy Chúa, con xin nương náu nơi Ngài khỏi những lời thì thầm của ma quỷ, và con xin nương tựa nơi Ngài, lạy Chúa của con, kẻo chúng đến gần con.", "Ẩn náu khỏi những lời thì thầm của satan.", "Một câu Kinh Qur'an về việc tìm kiếm nơi ẩn náu."),
        "dua_bad_character" to DuaText("Trốn tránh tính cách xấu", "Ôi Allah, tôi cầu xin Ngài nơi ẩn náu khỏi tính cách xấu, hành động xấu và ham muốn xấu xa.", "Trốn tránh tính cách xấu, hành động và ham muốn.", "Một nơi ẩn náu từ Nhà tiên tri ﷺ."),
        "dua_zawal_nimah" to DuaText("Quy y khỏi sự mất đi phước lành", "Ôi Allah, tôi cầu xin Ngài che chở khỏi sự mất mát phước lành của Ngài, khỏi sự thay đổi hạnh phúc mà Ngài đã ban cho, khỏi sự trừng phạt bất ngờ của Ngài và khỏi tất cả sự bất mãn của Ngài.", "Trốn tránh sự mất đi phước lành và tai họa bất ngờ.", "Bản dua của Nhà tiên tri ﷺ."),
        "dua_useless_knowledge" to DuaText("Quy y khỏi tri thức không lợi lạc", "Ôi Allah, tôi cầu xin Ngài che chở khỏi những kiến ​​thức vô ích, khỏi một trái tim không sợ hãi, khỏi một tâm hồn không bao giờ thỏa mãn và khỏi một câu hỏi không được đáp lại.", "Hãy trốn tránh những kiến ​​thức vô ích và một trái tim không sợ hãi Allah.", "Một nơi ẩn náu từ Nhà tiên tri ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Kiến thức hữu ích & Rizq Halal", "Ôi Allah, tôi cầu xin Ngài những kiến ​​​​thức bổ ích, sự cung cấp thuần khiết và những việc làm được chấp nhận.", "Sau lời cầu nguyện Fajr.", "Nhà tiên tri ﷺ đã nói điều này sau lễ salam của Fajr."),
        "dua_leprosy_diseases" to DuaText("Nơi ẩn náu khỏi những căn bệnh nghiêm trọng", "Lạy Allah, con cầu xin Ngài che chở khỏi bệnh bạch biến, bệnh điên, bệnh phong và mọi bệnh tật ác độc.", "Bảo vệ khỏi các bệnh nghiêm trọng.", "Một Sunnah dua để bảo vệ sức khỏe."),
        "dua_fear_people" to DuaText("Sợ kẻ thù hoặc kẻ áp bức", "Lạy Allah, chúng con đặt Ngài trước mặt họ và cầu xin Ngài che chở khỏi tội ác của họ.", "Khi lo sợ sự tổn hại của một người hay một người.", "Nhà tiên tri ﷺ đã nói điều này khi ông sợ hãi một dân tộc."),
        "dua_shirk_protection" to DuaText("Bảo vệ khỏi Hidden Shirk", "Ôi Allah, tôi cầu xin Ngài che chở để không cố ý liên kết bất cứ điều gì với Ngài và tôi cầu xin sự tha thứ của Ngài cho những gì tôi đã vô tình làm.", "Để giữ an toàn khỏi sự phô trương và trốn tránh ẩn giấu.", "Sự trốn tránh ẩn giấu còn được che giấu hơn cả sự bò lổm ngổm của một con kiến."),
        "dua_rain" to DuaText("Khi trời mưa", "Ôi Allah, (gửi) một cơn mưa có lợi.", "Khi trời đang mưa.", "Mưa là thời điểm mà các bộ đôi được chấp nhận."),
        "dua_after_rain" to DuaText("Sau cơn mưa", "Chúng ta đã được ban mưa nhờ ân huệ của Allah và lòng thương xót của Ngài.", "Sau cơn mưa.", "Người nói điều này là người tin vào Allah."),
        "dua_istisqa" to DuaText("Cầu mưa (Istisqa)", "Ôi Allah, hãy gửi mưa cho chúng tôi (ba lần).", "Khi không có mưa.", "Nhà tiên tri ﷺ đã thực hiện điều này trong bài giảng thứ Sáu và trời mưa."),
        "dua_heavy_rain" to DuaText("Mưa quá nhiều", "Ôi Allah, (hãy để nó rơi) xung quanh chúng tôi chứ không phải trên chúng tôi.", "Khi có quá nhiều mưa.", "Những đám mây đã di chuyển đi theo hướng của Nhà tiên tri ﷺ."),
        "dua_wind" to DuaText("Khi Gió Thổi", "Ôi Allah, tôi cầu xin Ngài những điều tốt lành cho nó, những điều tốt đẹp bên trong nó và những điều tốt đẹp của những gì nó được gửi đi cùng, và tôi cầu xin Ngài nơi trú ẩn khỏi những điều xấu xa của nó, những điều xấu xa bên trong nó và những điều xấu xa của những gì nó được gửi đi cùng.", "Khi có gió mạnh hoặc bão thổi.", "Nhà tiên tri ﷺ đã thực hiện điều này trong cơn bão."),
        "dua_thunder" to DuaText("Nghe thấy tiếng sấm", "Vinh quang thay Đấng mà sấm sét tôn vinh với lời khen ngợi của Ngài, và các thiên thần vì kính sợ Ngài.", "Khi nghe thấy tiếng sấm - việc thực hành của Abdullah ibn az-Zubayr (RA).", "Trích từ Surah ar-Ra'd (13:13)."),
        "dua_new_moon" to DuaText("Ngắm trăng mới", "Ôi Allah, hãy để mặt trăng này mọc lên trên chúng ta với phước lành, đức tin, sự an toàn và đạo Hồi. (Ôi mặt trăng,) Thượng đế của tôi và Thượng đế của bạn là Allah.", "Khi nhìn thấy mặt trăng mới.", "Sunnah dua cho mỗi tháng mới."),
        "dua_janaza_adult" to DuaText("Lời cầu nguyện Janaza (Người lớn)", "Lạy Allah, hãy tha thứ cho những người sống và những người đã chết của chúng tôi, những người có mặt và những người vắng mặt, người trẻ và người già, đàn ông và phụ nữ của chúng tôi. Ôi Allah, bất cứ ai trong chúng tôi mà Ngài giữ cho sống sót, hãy giữ cho anh ta sống sót theo đạo Hồi, và bất cứ ai trong chúng tôi mà Ngài khiến anh ta chết, hãy khiến anh ta chết vì đức tin.", "Sau takbir thứ ba của lời cầu nguyện tang lễ.", "Sunnah dua dành cho một người lớn đã qua đời."),
        "dua_janaza_child" to DuaText("Lời cầu nguyện Janaza (Trẻ em)", "Ôi Allah, hãy biến anh ấy thành người đi trước (và chủ nhà) cho chúng tôi, biến anh ấy thành phần thưởng và kho báu cho chúng tôi, và biến anh ấy thành người cầu thay cho chúng tôi mà lời cầu bầu của họ được chấp nhận.", "Trong lời cầu nguyện trong tang lễ của một đứa trẻ (đối với con gái hãy nói 'ij'alhā').", "Sunnah dua được thực hành bởi Hanafis."),
        "dua_mayyit_awf" to DuaText("Dua chi tiết cho người đã khuất", "Ôi Allah, hãy tha thứ cho anh ta, thương xót anh ta, ban cho anh ta hạnh phúc và tha thứ cho anh ta. Hãy làm cho sự tiếp đón của anh ta trở nên trang trọng và ngôi mộ của anh ta rộng rãi, rửa anh ta bằng nước, tuyết và mưa đá, và tẩy sạch tội lỗi cho anh ta như chiếc áo trắng được giặt sạch bụi bẩn.", "Trong tang lễ cầu nguyện hoặc cho người đã khuất.", "Awf ibn Malik (RA) ước gì mình là người đã khuất đó."),
        "dua_visiting_graves" to DuaText("Thăm mộ", "Bình an cho bạn, Hỡi những cư dân có đức tin và Hồi giáo trong những ngôi nhà này. Chúng tôi cũng vậy, nếu Allah muốn, sẽ tham gia cùng bạn. Tôi cầu xin Allah ban phúc lành cho chúng tôi và cho bạn.", "Khi vào nghĩa địa.", "Việc viếng thăm các ngôi mộ nhắc nhở người ta về cái chết và Đời sau."),
        "dua_closing_eyes" to DuaText("Khi nhắm mắt người quá cố", "Ôi Allah, hãy tha thứ cho (tên), hãy nâng cao thứ hạng của anh ấy trong số những người được hướng dẫn, hãy là người kế vị của anh ấy trong số những người mà anh ấy bỏ lại phía sau. Hỡi Chúa tể của thế giới, hãy tha thứ cho chúng tôi và anh ấy; hãy làm cho ngôi mộ của anh ấy rộng rãi và lấp đầy nó bằng ánh sáng.", "Khi nhắm mắt người đã khuất (nhắc đến tên người ấy).", "Nhà tiên tri ﷺ đã thực hiện bản dua này cho Abu Salamah (RA)."),
        "dua_condolence" to DuaText("Lời chia buồn (Ta'ziyah)", "Chắc chắn những gì Ngài lấy là của Allah và những gì Ngài đã cho là của Ngài, và mọi thứ với Ngài đều có thời hạn đã định, vì vậy hãy kiên nhẫn và hy vọng được khen thưởng.", "Gửi lời chia buồn tới một gia đình sau cái chết.", "Nhà tiên tri ﷺ đã gửi tin nhắn này cho con gái mình."),
        "dua_placing_in_grave" to DuaText("Đưa người đã khuất vào mộ", "Nhân danh Allah và trên con đường của Sứ giả Allah ﷺ.", "Khi hạ người quá cố xuống mộ.", "Lễ chôn cất Sunnah dua."),
        "dua_sneezing" to DuaText("Hắt hơi", "Mọi lời khen ngợi đều dành cho Allah. - Cầu xin Allah thương xót bạn. — Cầu mong Allah hướng dẫn bạn và giải quyết công việc của bạn một cách đúng đắn.", "Khi hắt hơi; người nghe nói 'Yarhamukallah', sau đó người hắt hơi trả lời.", "Đó là một trong những quyền của một người Hồi giáo đối với một người Hồi giáo khác."),
        "dua_toilet_enter" to DuaText("Vào nhà vệ sinh", "Nhân danh Allah. Ôi Allah, tôi cầu xin Ngài nơi ẩn náu khỏi jinn ô uế nam và nữ.", "Trước khi bước vào nhà vệ sinh bằng chân trái.", "Bismillah trở thành tấm bình phong giữa jinn và con người."),
        "dua_toilet_exit" to DuaText("Rời khỏi nhà vệ sinh", "(Lạy Allah) Tôi cầu xin sự tha thứ của Ngài.", "Khi bước ra khỏi nhà vệ sinh bằng chân phải.", "Nhà tiên tri ﷺ đã nói điều này khi rời khỏi nhà vệ sinh."),
        "dua_thanking" to DuaText("Cảm ơn ai đó", "Có thể Allah ban thưởng cho bạn những điều tốt đẹp.", "Khi ai đó giúp đỡ bạn.", "Ai nói điều này đã bày tỏ đầy đủ lời cảm ơn của mình."),
        "dua_love_for_allah" to DuaText("Khi ai đó nói 'Tôi yêu bạn vì Allah'", "Cầu mong Ngài (Allah), vì Ngài mà bạn yêu tôi, yêu bạn.", "Khi ai đó nói 'Tôi yêu bạn vì Chúa'.", "Sunnah đáp lại tình yêu vì lợi ích của Allah."),
        "dua_seeing_muslim_smile" to DuaText("Lời chào (Salaam)", "Bình an cho bạn, và lòng thương xót của Allah và phước lành của Ngài.", "Khi gặp một người Hồi giáo.", "Nói xong lễ Salam sẽ được ba mươi việc tốt."),
        "dua_dressing" to DuaText("Mặc quần áo", "Mọi lời khen ngợi đều dành cho Allah, Đấng đã mặc cho tôi thứ này và cung cấp nó cho tôi mà không cần bất kỳ sức mạnh hay quyền lực nào từ phía tôi.", "Khi mặc quần áo.", "Tin mừng về sự tha thứ tội lỗi trong quá khứ."),
    )
}
